char *getVehicleByIndex(char **vehicles, int size, int index) {
    if (index >= 0 && index < size) {
        return vehicles[index];
    } else {
        printf("Invalid index!\n");
        return NULL;
    }
}

int main() {
    int numOfVehicles; // Number of vehicles
    char *vehicles[100]; // Array to store vehicle names

    printf("Enter the number of vehicles: ");
    scanf("%d", &numOfVehicles);

    for (int i = 0; i < numOfVehicles; ++i) {
        printf("Enter vehicle %d name: ", i + 1);
        char vehicle[50];
        scanf("%s", vehicle);
        vehicles[i] = malloc(strlen(vehicle) + 1); // Allocate memory for the vehicle name
        strcpy(vehicles[i], vehicle);             // Copy the vehicle name to the array element
    }

    int index; // Index of the vehicle to get
    printf("Enter the index of a vehicle: ");
    scanf("%d", &index);
    char *vehicle = getVehicleByIndex(vehicles, numOfVehicles, index);
    if (vehicle != NULL) {
        printf("The selected vehicle is: %s\n", vehicle);
    }

    printArray(vehicles, numOfVehicles); // Print all vehicles

    for (int i = 0; i < numOfVehicles; ++i) {
        free(vehicles[i]); // Free memory allocated for each vehicle name
    }

    return 0;
}
