Create a new file `app.py`:

```python
from flask import Flask, request, redirect, url_for, render_template
from flask_sqlalchemy import SQLAlchemy
from flask_login import UserMixin, login_user, logout_user, current_user, login_required

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:////tmp/test.db'
db = SQLAlchemy(app)

class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(100), unique=True)
    password = db.Column(db.String(100))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form.get('email')
        password = request.form.get('password')
        user = User.query.filter_by(email=email).first()
        if user and user.password == password:
            login_user(user)
            return redirect(url_for('change_email'))
    return render_template('login.html')

@app.route('/logout')
def logout():
    logout_user()
    return redirect(url_for('login'))

@app.route('/change_email', methods=['GET', 'POST'])
@login_required
def change_email():
    if request.method == 'POST':
        old_email = request.form.get('old_email')
        new_email = request.form.get('new_email')
        confirm_password = request.form.get('confirm_password')

        user = User.query.filter_by(email=old_email).first()
        if user and user.password == current_user.password:
            if new_email != old_email:
                user.email = new_email
                db.session.commit()
        return redirect(url_for('login'))
    return render_template('change_email.html')

if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
```

Now, create a folder named `templates`, and within it, create two HTML files: `login.html` for login form and `change_email.html` for the email change form with appropriate fields for each form (old email, new email, password, confirm password).

```bash
touch templates/login.html
touch templates/change_email.html
```"]

