from flask import Flask, request, jsonify
import base64
from io import BytesIO
import PIL.Image as Image
import sqlite3

app = Flask(__name__)

def create_connection():
    conn = None
    try:
        conn = sqlite3.connect('images.db')
        return conn
    except Exception as e:
        print(e)
        return None

def init_table(conn):
    cursor = conn.cursor()
    cursor.execute('''CREATE TABLE IF NOT EXISTS images (name TEXT PRIMARY KEY, image_data BLOB)''')
    conn.commit()

def upload_image(conn):
    if request.method == 'POST':
        img_data = request.form['img_data']
        img_name = request.form['img_name']

        # Convert base64 string to image object
        img_data_bytes = base64.b64decode(img_data)
        img = Image.open(BytesIO(img_data_bytes))

        # Save the image to the database
        cursor = conn.cursor()
        cursor.execute("INSERT INTO images (name, image_data) VALUES (?, ?)", (img_name, img_data_bytes))
        conn.commit()

        return jsonify({"message": "Image uploaded successfully"})
    else:
        return "Invalid request method", 405

@app.route('/upload', methods=['POST'])
def upload():
    conn = create_connection()
    if not conn:
        return "Error creating the sqlite connection object", 500

    if init_table(conn):
        return upload_image(conn)
    else:
        return "Error initializing table", 500

if __name__ == '__main__':
