int scan(char buffer[], int size) {
    if (size <= 0) return -1; // invalid input size

    int count = 0;
    char c;

    while ((c = getchar()) != '\n') {
        if (count < size - 1) {
            buffer[count++] = c;
        } else {
            break;
        }
    }

    // ignore the newline character
    (void)getchar();

    buffer[count] = '\0'; // null terminate the string
    return count;
}
