[' Here's a simple C code example using `system()` function to execute the `ls` command and `printf()` function to create and print the command string. This code uses `stdarg.h` library for variable argument list support.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

void exec_ls(char *args, const char *delimiter) {
    pid_t pid;
    int status;
    char *arguments[128]; // max number of arguments for the system() call
    int count = 0;

    char *token = strtok(args, delimiter);
    while (token != NULL) {
        arguments[count++] = token;
        token = strtok(NULL, delimiter);
    }
    arguments[count] = NULL; // Null terminate the array.

    pid = fork();

    if (pid < 0) {
        perror("fork failed");
        return;
    } else if (pid == 0) {
        if(execvp(arguments[0], arguments) < 0){
            perror("Execution of the command failed");
            exit(1);
        }
    } else {
        waitpid(pid, &status, 0); // Wait for the child process to finish.
    }
}

void print_and_exec(const char *format, ...) {
    va_list args;
    char command[128]; // max length for a command string on most systems

    // Initialize argument list
    va_start(args, format);

    // Create command string with formatted arguments
    vsprintf(command, format, args);

    // Execute the created command string
    exec_ls(command, " ");

    // Clean up argument list
    va_end(args);
}

int main() {
    print_and_exec("ls -lh %s", "/tmp"); // Example usage of the print_and_exec function.
    return 0;
}
```

This code allows you to create and execute a command string using `printf()`-like syntax, with placeholders for the arguments specified in the format string (%s in this example). The given example executes the `ls -lh /tmp` command.']

[' Here's a C code using `popen()` and `printf()` functions to execute an ls command and print its output. The `printf()` function uses a format string with placeholders for the arguments.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

void execute_command(const char* command) {
    FILE * pipe;
    int pid;
    pid_t stat_pid;
    char buffer[128];

    pid = fork();
    if (pid < 0) {
        perror("fork failed");
        return;
    }

    if (pid == 0) {
        /* Child process */
        pipe = popen(command, "r");
        if (!pipe) {
            perror("popen() failed!");
            exit(1);
        }

        while (!feof(pipe)) {
            if (fgets(buffer, 128, pipe) != NULL)
                fputs(buffer, stdout);
        }

        pclose(pipe);
        exit(0);
    } else {
        /* Parent process */
        stat_pid = waitpid(pid, &WEXITSTATUS, 0);
        if (stat_pid <= 0) {
            perror("waitpid failed");
        }
    }
}

void print_ls(const char* dir) {
    printf("Executing ls command on %s\n", dir);
    execute_command(sprintf("/bin/ls -l %s", dir));
}

int main() {
    print_ls("/home");
    print_ls("/tmp");
    return 0;
}
```

This code defines a function `execute_command()` that executes the given command using `popen()`. The `print_ls()` function prints the output of ls command on specified directories. In the main function, the ls command is executed for both "/home" and "/tmp" directories.

Note: This code assumes a Unix-like system with standard libraries (glibc) and bash as the default shell. If you are using another environment, you may need to adjust the code accordingly.

Before running this code, make sure that the execution of external commands is enabled in your build environment. In GCC, you can enable it by adding `-lposix` flag when compiling:

```sh
gcc -o executable_name source_file.c -lposix
```']

[' Here's a simple C code snippet that uses `system()` to execute the `ls` command and `printf()` to create the string that is passed to `system()`. The format string for `printf()` includes placeholders for the arguments, in this case, an empty string because we are not using any specific file or directory.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char command[128];

    // Create the command string to be passed to system()
    sprintf(command, "ls");

    // Execute the command and store the result in err_msg
    char *err_msg = NULL;
    int status = system(command);

    if (WIFEXITED(status)) {
        // Command executed successfully, so print the exit status
        printf("Exit Status: %d\n", WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        // Command was terminated by a signal, so print the signal number
        printf("Signal: %d\n", WTERMSIG(status));
    } else {
        // Command failed for some reason, so print an error message
        err_msg = strdup("Command execution failed");
        perror(err_msg);
        free(err_msg);
    }

    return 0;
}
```

This code will execute the `ls` command and display the exit status or an error message if something goes wrong. The code also checks for termination by a signal, which may occur in certain circumstances (e.g., when a user interrupts the process with Ctrl+C).']

