    for (i = 0; argv[1][i]; ++i) {
        if (!isspace(argv[1][i])) {
            trimmed_string[j++] = argv[1][i];
        }
    }
    trimmed_string[j] = '\0';

    // Trim newlines
    for (i = 0; trimmed_string[i]; ++i) {
        if (trimmed_string[i] == '\n') {
            for (int k = i + 1; trimmed_string[k]; ++k) {
                trimmed_string[k - 1] = trimmed_string[k];
