import functools
import re
from urllib.parse import urlparse, urlunparse

def url_mapping(url):
    """Decorator that maps a URL to a function"""
    def decorate(func):
        _mapping = {url: func}

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            username = kwargs.get('username')
            if not username:
                raise ValueError("'username' is required for this function.")
            output = func(*args, username=username)
            return escape(output)

        return wrapper
    return decorate

def escape(text):
    """Converts special characters to HTML-safe sequences"""
    return re.sub(r'[&\"><\']', lambda x: {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;'}[x.group()], text)

@url_mapping('/hello/<username>')
def hello(username):
    """Function that returns a string with the text Hello followed by the value of the variable username"""
    return f"Hello {username}"

if __name__ == "__main__":
    import os
    from http.server import HTTPServer, SimpleHTTPRequestHandler
    from urllib.parse import urlencode

    # Create a simple web server to test our decorator
    server_port = int(os.environ.get('PORT', 8000))

    class CustomSimpleHTTPRequestHandler(SimpleHTTPRequestHandler):
        def do_GET(self):
            path = self.translate_path(self.path)
            if path == '/':
                path = 'index.html'
            try:
                with open(path, 'rb') as f:
                    self.send_response(200)
                    self.send_header('Content-Type', mimetypes.guess_type(path)[0])
                    self.end_headers()
                    self.wfile.write(f.read())
            except IOError:
                self.send_error(404, 'File not found')

    handler = CustomSimpleHTTPRequestHandler
    server = HTTPServer(('', server_port), handler)

    print("Serving on http://localhost:%s" % server_port)
    server.serve_forever()
```

